package com.yuegang.zhihui.inventory.security;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.security.InternalServiceSignature;import jakarta.servlet.http.HttpServletRequest;import java.time.*;import java.util.Set;public final class InventoryInternalSecurity{private static final Set<String>ALLOWED=Set.of("ygh-order-service","ygh-admin-service");private final InternalServiceSignature signatures;public InventoryInternalSecurity(byte[]k){signatures=new InternalServiceSignature(k,Clock.systemUTC(),Duration.ofSeconds(30));}public void verify(HttpServletRequest r){try{String service=h(r,"X-YGH-Service");if(!ALLOWED.contains(service))throw fail();Instant time=Instant.ofEpochMilli(Long.parseLong(h(r,"X-YGH-Service-Timestamp")));var m=new InternalServiceSignature.Metadata(service,r.getMethod(),r.getRequestURI(),time);if(!signatures.verify(m,h(r,"X-YGH-Service-Signature")))throw fail();}catch(BusinessException e){throw e;}catch(Exception e){throw fail();}}private static String h(HttpServletRequest r,String n){String v=r.getHeader(n);if(v==null||v.isBlank())throw fail();return v;}private static BusinessException fail(){return new BusinessException(ErrorCode.UNAUTHENTICATED);}}
